beforeFunction:
function yaclinic_gallery_collage_fields($field) {
    $doctor_field = 'field_sqns_doctor_before_after_cases' === ($field['key'] ?? '');
    $collage_key = $doctor_field ? 'field_yaclinic_doctor_case_collage' : 'field_yaclinic_case_collage';
    $layout_key = $doctor_field ? 'field_yaclinic_doctor_case_layout' : 'field_yaclinic_case_layout';
    $keys = array_column($field['sub_fields'] ?? array(), 'key');
    if (!in_array($collage_key, $keys, true)) {
        $collage_field = array(
            'key' => $collage_key, 'name' => 'collage_image',
            'label' => 'Целый коллаж До/После', 'type' => 'image',
            'return_format' => 'id', 'preview_size' => 'medium', 'library' => 'all',
            'parent' => $field['key'],
            'instructions' => 'Целый исходник без разрезания. Если заполнен, заменяет отдельные фото До и После только при показе.',
        );
        $layout_field = array(
            'key' => $layout_key, 'name' => 'comparison_layout',
            'label' => 'Подтверждённый порядок снимков в коллаже', 'type' => 'select',
            'choices' => array('' => 'Порядок пока не подтверждён', 'stacked' => 'До — сверху, После — снизу', 'side' => 'До — слева, После — справа', 'stacked_reverse' => 'После — сверху, До — снизу', 'side_reverse' => 'После — слева, До — справа'),
            'default_value' => '', 'allow_null' => 0, 'return_format' => 'value',
            'parent' => $field['key'],
        );
        acf_add_local_field($collage_field);
        acf_add_local_field($layout_field);
        $field['sub_fields'][] = $collage_field;
        $field['sub_fields'][] = $layout_field;
    }
    return $field;
}

